def find_writable_files(directory: str) -> list[str]:
    writable = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                st = os.stat(path)
                # World-writable eller skrivbar för nuvarande användare
                if st.st_mode & stat.S_IWOTH or os.access(path, os.W_OK):
                    writable.append(path)
            except (PermissionError, FileNotFoundError):
                continue
    return writable
