import math
import re
from collections import Counter
from scapy.all import rdpcap, DNS, DNSQR

def analyze_dns_traffic(pcap_file: str) -> dict:
    def entropy(s: str) -> float:
        c = Counter(s)
        return -sum((n / len(s)) * math.log2(n / len(s)) for n in c.values()) if s else 0

    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    query_counts = Counter()

    for pkt in rdpcap(pcap_file):
        if not (pkt.haslayer(DNS) and pkt.haslayer(DNSQR)):
            continue
        qname = pkt[DNSQR].qname.decode(errors="ignore").rstrip(".")
        if not qname:
            continue
        query_counts[qname] += 1
        labels = qname.split(".")
        subdomain = labels[0] if len(labels) > 2 else ""
        domain = ".".join(labels[-2:]) if len(labels) >= 2 else qname

        # DGA: hög entropi + få vokaler + långt namn
        core = labels[-2] if len(labels) >= 2 else qname
        vowel_ratio = sum(ch in "aeiou" for ch in core) / max(len(core), 1)
        if len(core) > 12 and entropy(core) > 3.5 and vowel_ratio < 0.3:
            suspicious["dga"].append(qname)

        # Tunneling: långa labels, TXT-frågor, många unika subdomäner
        if max(len(l) for l in labels) > 40 or (pkt[DNS].qdcount and pkt[DNSQR].qtype == 16):
            suspicious["tunneling"].append(qname)

        # Exfiltration: lång subdomän med base64/hex-liknande data
        if len(subdomain) > 30 and re.fullmatch(r"[A-Za-z0-9+/=_-]+", subdomain or ""):
            suspicious["exfiltration"].append(qname)

    # Frekvensbaserad tunneling-detektion
    for domain, count in query_counts.items():
        if count > 100 and domain not in suspicious["tunneling"]:
            suspicious["tunneling"].append(domain)

    return {k: sorted(set(v)) for k, v in suspicious.items()}
